sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        return;
    }

    g_form.getReference('requestor', function(requestor) {
        if (requestor.vip == 'true') {
            g_form.setValue('priority', '1');
            g_form.getDisplayBox('requestor').style.backgroundColor = 'red';
        } else {
            g_form.clearValue('priority');
            //  element.style.backgroundColor = '';
            g_form.getDisplayBox('requestor').style.backgroundColor = '';
        }
    });
}
